#!/usr/bin/env node
/**
 * Apply this repository's HubSpot template to the client's own HubSpot portal.
 *
 *   HUBSPOT_API_KEY=... node apply-hubspot-template.mjs [path/to/hubspot-template.json]
 *
 * Requires a HubSpot private app token generated by the CLIENT in their own portal
 * (Settings → Integrations → Private Apps — see crm/hubspot/README.md for a first-time,
 * click-by-click walkthrough) with crm.schemas.contacts.write, crm.schemas.companies.write,
 * and crm.objects.deals.write scopes. The token is only ever used for this one command;
 * deactivate the private app once the install is validated (the n8n workflows use their
 * own separate credential — see connectors/connector-checklist.md).
 *
 * Idempotent: re-running skips anything that already exists (matched by internal name),
 * so a partial failure — including "I closed my laptop halfway through" — is safe to retry.
 *
 * Deal pipeline creation requires HubSpot Pro+ (multiple pipelines). On Starter/Free,
 * this script skips pipeline creation and prints instructions to rename the existing
 * default pipeline manually — see hubspot-template.json's deal_pipeline.note_plan_tier.
 */

import { readFileSync } from 'node:fs';

const API = 'https://api.hubapi.com';
const KEY = process.env.HUBSPOT_API_KEY;
if (!KEY) {
  console.error('HUBSPOT_API_KEY is not set. Generate a private app token in your HubSpot portal (see crm/hubspot/README.md) and re-run.');
  process.exit(1);
}

const templatePath = process.argv[2] ?? new URL('./hubspot-template.json', import.meta.url);
const template = JSON.parse(readFileSync(templatePath, 'utf8'));

async function hubspot(method, path, body) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: { Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    const err = new Error(`${method} ${path} → ${res.status}: ${JSON.stringify(json)}`);
    err.status = res.status;
    throw err;
  }
  return json;
}

/** Create-if-missing helper: treat "already exists" conflicts as "already applied". */
async function ensure(label, fn) {
  try {
    const result = await fn();
    console.log(`  ✓ created ${label}`);
    return result;
  } catch (err) {
    if (err.status === 409 || /already exists|PROPERTY_ALREADY_EXISTS|duplicate/i.test(err.message)) {
      console.log(`  • ${label} already exists — skipped`);
      return null;
    }
    throw err;
  }
}

async function ensureLifecycleStageOptions(objectType, spec) {
  console.log(`\nlifecyclestage options (${objectType}):`);
  const current = await hubspot('GET', `/crm/v3/properties/${objectType}/${spec.internal_name}`);
  const existingValues = new Set((current.options ?? []).map((o) => o.value));
  const missing = spec.options.filter((o) => !existingValues.has(o.value));
  if (missing.length === 0) {
    console.log('  • all funnel stage options already present — skipped');
    return;
  }
  const mergedOptions = [...(current.options ?? []), ...missing.map((o, i) => ({
    label: o.label,
    value: o.value,
    displayOrder: (current.options?.length ?? 0) + i,
    hidden: false,
  }))];
  await ensure(`${missing.length} missing lifecyclestage option(s)`, () =>
    hubspot('PATCH', `/crm/v3/properties/${objectType}/${spec.internal_name}`, { options: mergedOptions }),
  );
}

async function ensureAssessmentProfileGroup(objectType, spec) {
  console.log(`\nProperty group (${objectType}):`);
  await ensure(`group "${spec.group_label}"`, () =>
    hubspot('POST', `/crm/v3/properties/${objectType}/groups`, {
      name: spec.group_name,
      label: spec.group_label,
    }),
  );

  console.log(`\nAssessment-profile properties (${objectType}):`);
  for (const prop of spec.properties) {
    await ensure(`property "${prop.label}"`, () =>
      hubspot('POST', `/crm/v3/properties/${objectType}`, {
        name: prop.name,
        label: prop.label,
        type: prop.type,
        fieldType: prop.fieldType,
        groupName: spec.group_name,
        options: prop.options?.map((label, i) => ({
          label,
          value: label.toLowerCase().replace(/[^a-z0-9]+/g, '_'),
          displayOrder: i,
          hidden: false,
        })),
      }),
    );
  }
}

async function ensureDealPipeline(spec) {
  console.log('\nDeal pipeline:');
  const { results: existing } = await hubspot('GET', '/crm/v3/pipelines/deals');
  // A3 fix: match the target pipeline BY NAME — a count-based check wrongly
  // skips creation on portals that have unrelated pipelines but not ours.
  const already = existing.find((p) => p.label === spec.name);
  if (already) {
    console.log(`  • pipeline "${spec.name}" already exists — skipping create.`);
    return;
  }
  try {
    await hubspot('POST', '/crm/v3/pipelines/deals', {
      label: spec.name,
      displayOrder: existing.length,
      stages: spec.stages.map((s) => ({
        label: s.label,
        displayOrder: s.order,
        metadata: {
          // A2 fix: HubSpot's pipeline API requires metadata values as STRINGS
          // ("true"/"false") — a JS boolean 400s the whole create.
          isClosed: String(Boolean(s.closed_won || s.closed_lost)),
          probability: s.closed_won ? '1.0' : s.closed_lost ? '0.0' : '0.5',
        },
      })),
    });
    console.log(`  ✓ created pipeline "${spec.name}"`);
  } catch (err) {
    // A2 follow-through: only genuine plan-tier messages get the tier
    // remediation — a blanket 400 match used to mask payload bugs as tier limits.
    if (/limit|not supported|plan/i.test(err.message)) {
      console.log('  • plan does not support multiple pipelines (Starter/Free tier).');
      console.log(`    Rename the existing default pipeline to "${spec.name}" manually:`);
      console.log('    Settings → Objects → Deals → Pipelines (this is a Settings-level action,');
      console.log('    not reachable via API — same boundary as lifecyclestage\'s display label).');
      return;
    }
    throw err;
  }
}

console.log(`Applying HubSpot template (v${template.kit_version}) — object type: ${template.object_type}`);

await ensureLifecycleStageOptions(template.object_type, template.lifecyclestage);
await ensureAssessmentProfileGroup(template.object_type, template.assessment_profile_properties);
await ensureDealPipeline(template.deal_pipeline);

console.log('\nDone. Next steps (manual, in the HubSpot UI):');
console.log('  1. Fill the assessment-profile properties on your own Harness Install contact/company');
console.log('     record — same fields as status/status.json.');
console.log('  2. Confirm hs_buying_role = DECISION_MAKER is set on the decision-maker contact.');
console.log('  3. If the pipeline step was skipped (plan tier), rename the default pipeline by hand.');